"use strict";(globalThis.webpackChunkgrc||=[]).push([[16689],{11873(e){e.exports=JSON.parse('{"citeKey":"feng2015lcindex","slug":"feng-2015-lcindex--e3f4","title":"LCIndex, A Local and Clustering Index on Distributed Ordered Tables for Multi-Dimensional Range Queries","authors":["C. Feng","X. Yang","F. Liang","X.-H. Sun","Z. Xu"],"venue":"44th International Conference on Parallel Processing (ICPP\'15), Beijing, China","type":"Conference","entryType":"inproceedings","date":"September, 2015","year":2015,"era":"iit","month":9,"doi":"10.1109/icpp.2015.81","abstract":"A lot of Not Only SQL (NoSQL) databases have been proposed in the era of big data. Distributed Ordered Table (DOT) is one kind of NoSQL database that has attracted lots of attention. It horizontally partitions table into regions and distributes regions to region servers according to the keys. Multi-Dimensional Range Query (MDRQ) is a common operation over DOTs. Many indexing techniques have been proposed to improve the performance of MDRQ, but they cannot guarantee high performance on both insert and flexible MDRQ at the same time. In this paper, we propose a novel indexing technique named LCIndex, short for Local and Clustering Index, to solve this issue. Experimental results confirm that LCIndex can achieve high performance on both insert operations and flexible MDRQ.","hasAbstract":true,"lede":"We propose a novel indexing technique named LCIndex, short for Local and Clustering Index, to solve this issue.","links":{"pdf":"https://grc.iit.edu/papers/2015/feng-2015-lcindex--e3f4.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);